(function(){"use strict";function e(){document.querySelectorAll(".copy-btn").forEach(e=>{e.addEventListener("click",()=>{const t=e.closest(".code-block")?.querySelector("code");if(!t)return;navigator.clipboard.writeText(t.textContent).then(()=>{const t=e.textContent;e.textContent="Copied!",e.classList.add("copied"),setTimeout(()=>{e.textContent=t,e.classList.remove("copied")},1500)})})})}function t(){const e=document.getElementById("terminfo-search"),t=document.getElementById("terminfo-list");if(!e||!t)return;const n=t.querySelectorAll(".terminfo-item");e.addEventListener("input",()=>{const t=e.value.toLowerCase().trim();n.forEach(e=>{const n=e.dataset.name||"",s=e.textContent.toLowerCase(),o=!t||n.includes(t)||s.includes(t);e.classList.toggle("hidden",!o)})})}document.addEventListener("DOMContentLoaded",()=>{e(),t()})})()